// Teaching notes are concise prompts for discussion, prediction, and explanation.

const glossary=[['Problem representation','Keep the states, actions, constraints, goal, and cost needed to solve a task.'],['Supervised learning','Learn from example inputs paired with known target labels.'],['Unsupervised learning','Find structure in examples without supplied target labels.'],['Semi-supervised learning','Use labelled and unlabelled examples in learning.'],['Reinforcement learning','Learn behaviour from feedback or rewards following actions.'],['Leakage','Information used in learning or evaluation that would not properly be available at prediction time.'],['Deep learning','Machine learning based on neural networks with multiple layers.'],['Weight','A parameter multiplying an input contribution.'],['Bias','An offset added to a weighted sum.'],['ReLU','The activation max(0, score): positive values pass through and negative values become zero.'],['State','A representation of the current situation relevant to a problem.'],['Frontier','Discovered candidates waiting for selection in a search.'],['BFS','Breadth-first search: select by fewest steps from the start using queue order.'],['Uniform-cost search','Select by lowest accumulated path cost; used here with nonnegative costs.'],['Heuristic','An estimate or rule of thumb used to guide a choice.'],['A*','A search method selecting by cost so far g plus estimated remaining cost h.'],['Knowledge representation','A format for meaningful facts, relationships, rules, or beliefs.'],['Unknown','A deliberately separate value when the required evidence is missing.'],['Provenance','The source and relevant context of a fact or claim.'],['Deduction','A conclusion justified by valid rules under the given premises.'],['Induction','Generalising from examples with uncertainty.'],['Abduction','A plausible explanation for observations rather than a guaranteed cause.'],['Predicate','A property or relation applied to an entity or entities.'],['Recall','TP/(TP+FN): fraction of actual positives caught.'],['Precision','TP/(TP+FP): fraction of predicted positives that are real positives.'],['Accuracy','(TP+TN)/total: fraction of correct predictions.'],['F1','2TP/(2TP+FP+FN): combines precision and recall when the ratio is defined.'],['MAE','Mean absolute error: average absolute difference in the target’s units.'],['Grounding','Connect a factual answer to relevant supporting evidence.'],['Few-shot prompting','Input/output demonstrations included in a request’s context.'],['Conversation context','Earlier messages or supported linked state deliberately supplied to a follow-up.'],['Token','A model-processing unit that may be a part of a word.'],['Capstone','An integrated practice task connecting several course concepts.']];
const stage=document.getElementById('stage');let lastFocus=null,seconds=7200,timerRunning=false,timerInterval=null;
function go(i){state.slide=Math.max(0,Math.min(slides.length-1,Number(i)||0));save();render();window.scrollTo({top:0,behavior:'instant'});}
function render(){const i=state.slide,s=slides[i];document.title='Session 06 · '+s.title;stage.innerHTML='<article class="slide session06"><div class="slide-head"><div class="section-label"><span class="rule"></span><span class="eyebrow">'+esc(s.kicker)+'</span></div>'+(i===0?'':'<h2>'+esc(s.title)+'</h2>')+'</div>'+s.html()+'</article>';document.getElementById('pageLabel').textContent=(i+1)+' / '+slides.length+' · '+sectionFor(i).name;document.getElementById('prevBtn').disabled=i===0;document.getElementById('nextBtn').disabled=i===slides.length-1;document.getElementById('progressFill').style.width=((i+1)/slides.length*100)+'%';document.getElementById('progress').setAttribute('aria-valuenow',i+1);document.getElementById('progress').setAttribute('aria-valuemax',slides.length);if(i===6)updateWorkflow();if(i===10)updateNeuron();if(i===16)updateSearch();if(i===20)updateLogic();if(i===24)updateSort();if(i===25)updateMetrics();if(i===29)updateRepair();if(i===34)document.getElementById('capstoneOutput').classList.toggle('bad',['unknown','blocked','unreachable'].includes(state.capstoneResult?.kind));}
function downloadText(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadWork(){const names={mlPlan:'ML scenario',neuronReason:'Changed neuron explanation',searchTransfer:'New search problem',knowledgeChange:'Changed evidence and conclusion',metricReport:'Metric calculations and evidence',pythonReason:'Request mistake and remedy',capstonePlan:'Own capstone design and test cases',finalReflection:'Reflection and next practice'};const parts=['FOUNDATIONS OF AI · SESSION 06','Original supplementary practice · '+new Date().toLocaleDateString()];for(const [k,n] of Object.entries(names))parts.push(n+'\n'+(state.worksheet[k]||'[Not answered]'));parts.push('WORKFLOW\n'+state.workflow.join(' → '),'TOY NEURON\n'+JSON.stringify(state.neuron)+'\n'+JSON.stringify(neuronValues(state.neuron)),'SEARCH CONFIGURATION\n'+state.algorithm+', '+state.costMode+', roads '+state.roads,'CURRENT SEARCH RESULT\n'+JSON.stringify(state.engine?.result||'[Not run]'),'THREE-VALUED FACTS\n'+JSON.stringify(state.facts)+'\nAccess condition: '+truth(accessDecision(state.facts)),'CONFUSION SORTING\n'+JSON.stringify(state.sort),'METRIC COUNTS AND RESULTS\n'+JSON.stringify(state.counts)+'\n'+JSON.stringify(computeMetrics(state.counts)),'LOCAL CAPSTONE RESULT\n'+(state.capstoneResult?.text||'[Not run]'),'SELF-REPORTED SKILLS\n'+skills.map(([k,n])=>(state.skills[k]?'Demonstrated to partner: ':'Practise further: ')+n).join('\n'),'QUIZ CHECKS');for(const [id,q] of Object.entries(quizData))parts.push(id+': '+(state.answers[id]===undefined?'not answered':state.answers[id]===q.correct?'correct':'review needed'));parts.push('These records are original practice and self-reported reflection, not an official textbook completion record or exam grade.');downloadText('session-06-my-course-practice.txt',parts.join('\n\n'));}
function glossaryHTML(query=''){return glossary.filter(x=>x.join(' ').toLowerCase().includes(query.toLowerCase())).map(([w,m])=>'<div class="glossary-item"><b>'+esc(w)+'</b><p>'+esc(m)+'</p></div>').join('')||'<p>No matching term.</p>';}
function timerText(){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
function updateTimer(){const v=document.getElementById('timerValue'),b=document.getElementById('timerToggle');if(v)v.textContent=timerText();if(b)b.textContent=timerRunning?'Pause':'Start';}
function openDrawer(type){lastFocus=document.activeElement;document.getElementById('drawer').hidden=false;const title=document.getElementById('drawerTitle'),body=document.getElementById('drawerBody');if(type==='outline'){title.textContent='Session contents';body.innerHTML='<div class="panel stack"><div class="row between"><h3>Class timer</h3><b id="timerValue">'+timerText()+'</b></div><div class="row"><button id="timerToggle">'+(timerRunning?'Pause':'Start')+'</button><button id="timerReset">Reset 120 min</button></div></div>'+slides.map((s,i)=>'<button class="outline-button '+(i===state.slide?'current':'')+'" data-outline-go="'+i+'"><span>'+String(i+1).padStart(2,'0')+'</span>'+esc(s.title)+'</button>').join('');}else if(type==='sources'){title.textContent='Coverage and references';body.innerHTML='<p>The supplied April 2026 Aptech presenter’s manual requires the textbook’s Try It Yourself questions from Book Sessions 1–7 for class 6. Those questions and the ProConnect assignments were not supplied.</p><p>This presentation contains original revision exercises aligned to those topic headings. The Book checklist records actual references and teacher-confirmed coverage when available, separately from original work.</p><p>Revision mapping: Book1 AI/ML; Book2 deep learning; Book3 agents/problem formulation; Book4 search; Book5 knowledge; Book6 reasoning/metrics/emerging AI; Book7 Python prompts/context.</p><a class="source-link06" href="https://aima.cs.berkeley.edu/" target="_blank" rel="noopener">Artificial Intelligence: A Modern Approach · further reading</a><a class="source-link06" href="https://scikit-learn.org/stable/modules/model_evaluation.html" target="_blank" rel="noopener">scikit-learn · metric definitions</a><a class="source-link06" href="https://developers.openai.com/api/docs/guides/conversation-state" target="_blank" rel="noopener">Official OpenAI conversation-state guidance</a><a class="source-link06" href="session-05.html">Session 5 · current API references and Python examples</a><p>Facts, graph costs, labels, and numerical examples are fictional. Every interactive calculation is local. No API or language model runs here. The three-valued rule is a deliberately chosen teaching model.</p><p>The earlier S1, S2, and S3 activities total the manual’s six self-study hours. No additional required self-study block is created by this revision class.</p>';}else{title.textContent='Word bank';body.innerHTML='<label for="wordSearch" class="small">Find a term</label><input id="wordSearch" type="text" placeholder="Bias, recall, context…"><div id="wordList">'+glossaryHTML()+'</div>';}document.getElementById('closeDrawer').focus();}
function closeDrawer(){document.getElementById('drawer').hidden=true;if(lastFocus?.isConnected)lastFocus.focus();}
stage.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go!==undefined)return go(b.dataset.go);if(b.dataset.exitTab!==undefined){state.exitTab=Number(b.dataset.exitTab);save();render();return;}if(b.dataset.quiz){const id=b.dataset.quiz,a=Number(b.dataset.choice),q=quizData[id];state.answers[id]=a;save();document.querySelectorAll('[data-quiz="'+id+'"]').forEach(x=>x.setAttribute('aria-pressed',Number(x.dataset.choice)===a));const f=document.getElementById('feedback-'+id);f.textContent=(a===q.correct?'Yes. ':'Review the reason. ')+q.why;f.classList.toggle('bad',a!==q.correct);}if(b.dataset.workflowMove!==undefined){const i=Number(b.dataset.workflowMove),j=i+Number(b.dataset.direction);if(j>=0&&j<state.workflow.length){[state.workflow[i],state.workflow[j]]=[state.workflow[j],state.workflow[i]];state.workflowChecked=false;save();updateWorkflow();}}if(b.dataset.workflowInfo){const s=workflowSteps.find(s=>s.id===b.dataset.workflowInfo);document.getElementById('workflowReason').innerHTML='<h3>'+s.title+'</h3><p>'+s.why+'</p>';}if(b.id==='checkWorkflow'){state.workflowChecked=true;save();updateWorkflow();}if(b.id==='resetWorkflow'){state.workflow=structuredClone(fresh.workflow);state.workflowChecked=false;save();updateWorkflow();}if(b.id==='resetNeuron'){state.neuron=structuredClone(fresh.neuron);save();render();}if(b.dataset.neuronLine!==undefined){const i=Number(b.dataset.neuronLine);document.querySelectorAll('[data-neuron-line]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.getElementById('neuronLineDetail').innerHTML='<h3>Line '+(i+1)+'</h3><pre class="code">'+esc(neuronLines[i][0])+'</pre><p>'+neuronLines[i][1]+'</p>';}if(b.id==='searchStep'){stepSearch(state.engine);save();updateSearch();}if(b.id==='searchRun'){for(let i=0;i<50&&!state.engine.result;i++)stepSearch(state.engine);save();updateSearch();}if(b.id==='searchReset'){resetSearch();updateSearch();}if(b.dataset.mapNode){const id=b.dataset.mapNode;document.getElementById('nodeDetail').textContent=mapNodes[id].name+': '+(neighbours(id,state.costMode,roadSets[state.roads]).map(n=>n.node+' (cost '+n.cost+')').join(', ')||'no open neighbours');}if(b.id==='checkSort'){state.sortChecked=true;save();updateSort();}if(b.id==='resetSort'){state.sort={};state.sortChecked=false;save();updateSort();}if(b.id==='useCardCounts'){state.counts=correctCounts();state.metricScenario='cards';save();go(25);}if(['cardMetricCase','imbalanceCase','emptyMetricCase'].includes(b.id)){state.counts=b.id==='cardMetricCase'?correctCounts():b.id==='imbalanceCase'?{tp:0,fp:0,fn:5,tn:95}:{tp:0,fp:0,fn:0,tn:0};state.metricScenario=b.id==='imbalanceCase'?'imbalance':b.id==='emptyMetricCase'?'empty':'cards';save();render();}if(b.id==='checkRepairs')updateRepair(true);if(b.id==='runCapstone'){state.capstoneResult=capstoneAnswer(state.capstone);save();const f=document.getElementById('capstoneOutput');f.textContent=state.capstoneResult.text;f.classList.toggle('bad',['unknown','blocked','unreachable'].includes(state.capstoneResult.kind));}if(b.id==='downloadFinal'||b.id==='downloadWork')downloadWork();if(b.id==='sourcesBtn')openDrawer('sources');});
stage.addEventListener('input',e=>{const t=e.target;if(t.dataset.field){state.worksheet[t.dataset.field]=t.value;save();}if(t.dataset.neuron){state.neuron[t.dataset.neuron]=Number(t.value);save();updateNeuron();}if(t.dataset.count){state.counts[t.dataset.count]=t.value===''?null:Number(t.value);state.metricScenario='custom';save();updateMetrics();}});
stage.addEventListener('change',e=>{const t=e.target;if(t.id==='activation'){state.neuron.activation=t.value;save();updateNeuron();}if(t.id==='searchAlgorithm'||t.id==='costMode'||t.id==='roads'){state[t.id==='searchAlgorithm'?'algorithm':t.id]=t.value;resetSearch();updateSearch();document.getElementById('nodeDetail').textContent='Select a node to inspect its available neighbours.';}if(t.dataset.triGroup){state[t.dataset.triGroup][t.dataset.triKey]=t.value==='unknown'?null:t.value==='true';if(t.dataset.triGroup==='facts'){save();updateLogic();}else{state.capstoneResult=null;save();document.getElementById('capstoneOutput').textContent='Predict the answer with the changed facts.';document.getElementById('capstoneOutput').classList.remove('bad');}}if(t.dataset.sort){state.sort[t.dataset.sort]=t.value;state.sortChecked=false;save();document.querySelectorAll('.sort-card06').forEach(card=>{card.classList.remove('correct06','wrong06');card.querySelector('small')?.remove();});const f=document.getElementById('sortResult');f.classList.remove('bad');f.textContent='Choices changed. Check the sorting again.';}if(t.dataset.repair){state.repairs[t.dataset.repair]=t.value;save();updateRepair();}if(t.id==='capstoneQuestion'||t.id==='capstoneRoads'){state.capstone[t.id==='capstoneQuestion'?'question':'roads']=t.value;state.capstoneResult=null;save();document.getElementById('capstoneOutput').textContent='Predict the answer with the changed case.';document.getElementById('capstoneOutput').classList.remove('bad');}if(t.dataset.skill){state.skills[t.dataset.skill]=t.checked;save();}});
document.getElementById('prevBtn').onclick=()=>go(state.slide-1);document.getElementById('nextBtn').onclick=()=>go(state.slide+1);document.getElementById('outlineBtn').onclick=()=>openDrawer('outline');document.getElementById('glossaryBtn').onclick=()=>openDrawer('glossary');document.getElementById('closeDrawer').onclick=closeDrawer;document.getElementById('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch(e){document.getElementById('fullscreenBtn').textContent='Use browser full screen';}};
document.getElementById('drawer').addEventListener('click',e=>{if(e.target.id==='drawer')closeDrawer();const b=e.target.closest('button');if(!b)return;if(b.dataset.outlineGo!==undefined){closeDrawer();go(b.dataset.outlineGo);}if(b.id==='timerToggle'){timerRunning=!timerRunning;if(timerRunning)timerInterval=setInterval(()=>{if(seconds>0)seconds--;else{timerRunning=false;clearInterval(timerInterval);}updateTimer();},1000);else clearInterval(timerInterval);updateTimer();}if(b.id==='timerReset'){seconds=7200;timerRunning=false;clearInterval(timerInterval);updateTimer();}});
document.getElementById('drawer').addEventListener('input',e=>{const t=e.target;if(t.id==='wordSearch')document.getElementById('wordList').innerHTML=glossaryHTML(t.value);});
document.addEventListener('keydown',e=>{const drawer=document.getElementById('drawer');if(e.key==='Escape'&&!drawer.hidden){closeDrawer();return;}if(!drawer.hidden){if(e.key==='Tab'){const all=[...drawer.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled),first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='ArrowRight'){e.preventDefault();go(state.slide+1);}if(e.key==='ArrowLeft'){e.preventDefault();go(state.slide-1);}if(e.key==='Home'){e.preventDefault();go(0);}if(e.key==='End'){e.preventDefault();go(slides.length-1);}});
if(!state.engine)resetSearch();state.slide=Math.max(0,Math.min(slides.length-1,Number(state.slide)||0));render();
